static uint8_t __attribute__((aligned(8))) chunk[PQC_CHUNK_SIZE]; // RAM buffer for one streamed piece; set to the SPI read size (e.g. 4096) for real data 


#if defined(CONFIG_BOARD_MEC172XMODULAR_ASSY6930)
#include "rom_api.h"

static int mchp_init_config(void) {
    int ret;

    LOG_INF("--- Zephyr Boot rom test ---");

    do {
        const uint8_t *pk = PqcTestPubKey;
        const uint8_t *sig = PqcTestSig;
        const uint8_t *msg = PqcTestMsg;

        unsigned char random128[16] = {0};
        int result;

        LOG_INF("api_mchp_fips204_verify start");
        result = api_mchp_fips204_verify(
            sig, PQC_SIG_SIZE, msg, PQC_TEST_MSG_SIZE, NULL, 0, pk,
            PQC_PUBKEY_SIZE, random128, MLDSA87_LEVEL);
        LOG_INF("api_mchp_fips204_verify: %d", result);
    } while (0);

    do {
        const uint8_t *pk = PqcSamplePubKey;
        const uint8_t *sig = PqcSampleSig;
        const uint8_t *msg = PqcSampleMsg;
        uint8_t random128[16] = {0};
        mchp_fips204_ctx_t state;
        int result;

        LOG_INF("api_mchp_fips204_verify_begin start");
        ret = api_mchp_fips204_verify_begin(NULL, 0, pk, PQC_PUBKEY_SIZE, random128, &state,
                                           MLDSA87_LEVEL);
        if (ret) {
            LOG_ERR("api_mchp_fips204_verify_begin: %d", ret);
        }

        for (uint32_t off = 0; off < PQC_SAMPLE_MSG_SIZE; off += PQC_CHUNK_SIZE) {
            uint32_t size = MIN(PQC_CHUNK_SIZE, PQC_SAMPLE_MSG_SIZE - off);

            LOG_DBG("api_mchp_fips204_verify_update offset: 0x%04x", off);
            ret = api_mchp_fips204_verify_update(&msg[off], size, &state);
            if (ret) {
                LOG_ERR("api_mchp_fips204_verify_update: %d", ret);
            }
        }

        result = api_mchp_fips204_verify_finish(sig, PQC_SIG_SIZE, pk, PQC_PUBKEY_SIZE, random128,
                                              &state, MLDSA87_LEVEL);
        LOG_INF("api_mchp_fips204_verify_finish: %d", result);

    } while (0);
    return 0;
}

SYS_INIT(mchp_init_config, APPLICATION, 0);

#endif // CONFIG_BOARD_MEC172XMODULAR_ASSY6930

#if defined(CONFIG_WOLFSSL_MLDSA)

#include <wolfssl/wolfcrypt/wc_mldsa.h>
#include <wolfssl/wolfcrypt/sha3.h>
#include <wolfssl/wolfcrypt/error-crypt.h>

static int init_config(void) {
    int ret;

    LOG_INF("--- Zephyr Boot rom test ---");

    do {
        const uint8_t *pk = PqcTestPubKey;
        const uint8_t *sig = PqcTestSig;
        const uint8_t *msg = PqcTestMsg;
        wc_MlDsaKey mldsa_key;
        int verify_res = 0;

        /* 1. Initialize the ML-DSA key structure */
        /* Args: key pointer, heap hint (usually NULL on embedded), device ID */
        ret = wc_MlDsaKey_Init(&mldsa_key, NULL, INVALID_DEVID);
        if (ret != 0) {
            LOG_ERR("Error: ML-DSA key init failed (code: %d)", ret);
            return ret;
        }

        /* 2. Pre-provisioned ML-DSA-87 public key and signature */
        /* In practice these are read from flash, an OTA buffer or an HSM */
        // static uint8_t mock_public_key[PQC_PUBKEY_SIZE];
        // static uint8_t mock_signature[PQC_SIG_SIZE];

        // Placeholder fill only; replace with the real key and signature
        // memset(mock_public_key, 0x1A, sizeof(mock_public_key));
        // memset(mock_signature,  0x2B, sizeof(mock_signature));

        /* 3. Set the security level to ML-DSA-87, then import the raw public key */
        ret = wc_MlDsaKey_SetParams(&mldsa_key, WC_ML_DSA_87);
        if (ret == 0) {
            ret = wc_MlDsaKey_ImportPubRaw(&mldsa_key, pk, PQC_PUBKEY_SIZE);
        }
        if (ret != 0) {
            LOG_ERR("Error: public key import failed (code: %d, msg: %s)", ret,
                    wc_GetErrorString(ret));
            wc_MlDsaKey_Free(&mldsa_key);
            return ret;
        }
        LOG_INF("ML-DSA-87 public key loaded");

        /* 4. Prepare the message to verify */
        // const uint8_t message[] = "Secure Firmware Payload V1.0.0 -
        // Post-Quantum Protected"; size_t message_len = sizeof(message) - 1;

        LOG_INF("Running FIPS 204 Level 5 signature verification (heavy "
                "computation)...");

        /* 5. Run FIPS 204 signature verification */
        /* Args: key, signature, signature size, context (empty), context
         * length, message, message size, result output pointer */
        ret = wc_MlDsaKey_VerifyCtx(&mldsa_key, sig, PQC_SIG_SIZE, NULL, 0, msg,
                                    PQC_TEST_MSG_SIZE, &verify_res);

        /* 6. Check the verification result */
        /* Note: wc_MlDsaKey_VerifyCtx returns 0 when it runs successfully;
         * the signature is valid only if verify_res is 1 */
        if (ret == 0 && verify_res == 1) {
            LOG_INF("[PASS] FIPS 204 (ML-DSA-87) signature verified, firmware "
                    "is valid");
        } else {
            LOG_ERR("[FAIL] Signature verification failed");
            LOG_ERR("Details -> ret: %d (%s), verify_res: %d", ret,
                    wc_GetErrorString(ret), verify_res);
        }

        /* 7. Free key resources to avoid memory leaks */
        wc_MlDsaKey_Free(&mldsa_key);
        LOG_INF("=== Verification done ===");
    } while (0);

    do {
        /* Streaming ML-DSA-87 verify of a 128KB message (wolfSSL).
         * FIPS 204: mu = SHAKE256(tr || 0x00 || ctxLen || ctx || M, 64), tr =
         * SHAKE256(pk, 64) mu is computed chunk by chunk, then checked with
         * wc_MlDsaKey_VerifyMu(). */
        const uint8_t *pk = PqcSamplePubKey;
        const uint8_t *sig = PqcSampleSig;
        const uint8_t *msg = PqcSampleMsg;
        const uint8_t prefix[2] = {0x00, 0x00}; /* pure ML-DSA, empty context */
        uint8_t tr[MLDSA_TR_SZ];
        uint8_t mu[MLDSA_MU_SZ];
        wc_MlDsaKey mldsa_key;
        wc_Shake shake;
        int verify_res = 0;

        ret = wc_MlDsaKey_Init(&mldsa_key, NULL, INVALID_DEVID);
        if (ret != 0) {
            LOG_ERR("Error: ML-DSA key init failed (code: %d)", ret);
            return ret;
        }

        ret = wc_MlDsaKey_SetParams(&mldsa_key, WC_ML_DSA_87);
        if (ret == 0) {
            ret = wc_MlDsaKey_ImportPubRaw(&mldsa_key, pk, PQC_PUBKEY_SIZE);
        }
        if (ret != 0) {
            LOG_ERR("Error: public key import failed (code: %d, msg: %s)", ret,
                    wc_GetErrorString(ret));
            wc_MlDsaKey_Free(&mldsa_key);
            return ret;
        }
        LOG_INF("ML-DSA-87 public key loaded");

        /* begin: tr = SHAKE256(pk), then start mu with tr || prefix */
        ret = wc_InitShake256(&shake, NULL, INVALID_DEVID);
        if (ret == 0) {
            ret = wc_Shake256_Update(&shake, pk, PQC_PUBKEY_SIZE);
        }
        if (ret == 0) {
            ret = wc_Shake256_Final(&shake, tr, sizeof(tr));
        }
        if (ret == 0) {
            ret = wc_Shake256_Update(&shake, tr, sizeof(tr));
        }
        if (ret == 0) {
            ret = wc_Shake256_Update(&shake, prefix, sizeof(prefix));
        }

        /* update: feed the message chunk by chunk */
        for (uint32_t off = 0; (ret == 0) && (off < PQC_SAMPLE_MSG_SIZE);
             off += PQC_CHUNK_SIZE) {
            uint32_t size = MIN(PQC_CHUNK_SIZE, PQC_SAMPLE_MSG_SIZE - off);

            LOG_DBG("shake256 update offset: 0x%05x", off);
            memcpy(chunk, &msg[off],
                   size); /* stands in for the SPI flash read */
            ret = wc_Shake256_Update(&shake, chunk, size);
        }

        /* finish: mu, then verify */
        if (ret == 0) {
            ret = wc_Shake256_Final(&shake, mu, sizeof(mu));
        }
        wc_Shake256_Free(&shake);

        if (ret == 0) {
            LOG_INF("Running FIPS 204 Level 5 signature verification (128KB "
                    "stream)...");
            ret = wc_MlDsaKey_VerifyMu(&mldsa_key, sig, PQC_SIG_SIZE, mu,
                                       sizeof(mu), &verify_res);
        }

        if (ret == 0 && verify_res == 1) {
            LOG_INF("[PASS] FIPS 204 (ML-DSA-87) 128KB signature verified");
        } else {
            LOG_ERR("[FAIL] Signature verification failed");
            LOG_ERR("Details -> ret: %d (%s), verify_res: %d", ret,
                    wc_GetErrorString(ret), verify_res);
        }

        wc_MlDsaKey_Free(&mldsa_key);
        LOG_INF("=== Verification done ===");
    } while (0);

    return 0;
}

SYS_INIT(init_config, APPLICATION, 0);
#endif // CONFIG_WOLFSSL_MLDSA
